def _sanitize_check_name(name: str) -> str:
    """Convert any string to a valid Dagster check name.

    Replaces all characters that are not alphanumeric or underscore with ``_``,
    truncates to 100 characters, strips leading/trailing underscores, and returns
    ``"check"`` if the result is empty.
    """
    sanitized = re.sub(r"[^0-9a-zA-Z_]", "_", name)
    sanitized = sanitized[:100]
    sanitized = sanitized.strip("_")
    return sanitized or "check"


def _parse_check_identifiers_from_yaml(yaml_path: Path, dataset: str) -> list[str]:
    """Read a SodaCL YAML file and return sanitized check identifiers for ``dataset``.

    Looks for the key ``"checks for {dataset}"`` in the YAML. For plain string items,
    sanitizes via :func:`_sanitize_check_name`. For dict items with a ``"name"`` key in
    the config, uses that name value directly. Returns ``[]`` if the dataset key is not
    found or the file is empty.
    """
    with open(yaml_path) as f:
        parsed = yaml.safe_load(f)

    if not parsed:
        return []

    checks_key = f"checks for {dataset}"
    checks = parsed.get(checks_key)
    if not checks:
        return []

    identifiers: list[str] = []
    for item in checks:
        if isinstance(item, str):
            identifiers.append(_sanitize_check_name(item))
        elif isinstance(item, dict):
            for _check_expression, config in item.items():
                if isinstance(config, dict) and "name" in config:
                    identifiers.append(config["name"])
                else:
                    identifiers.append(_sanitize_check_name(_check_expression))
    return identifiers


def _collect_check_identifiers_for_dataset(
    checks_paths: list[str], project_root: Path, dataset: str
) -> list[str]:
    """Aggregate check identifiers from multiple SodaCL YAML files for ``dataset``.

    Resolves relative paths against ``project_root``.
    """
    identifiers: list[str] = []
    for checks_path in checks_paths:
        path = Path(checks_path)
        if not path.is_absolute():
            path = project_root / path
        identifiers.extend(_parse_check_identifiers_from_yaml(path, dataset))
    return identifiers


def _get_outcome(soda_check: Any) -> str:
    """Extract an outcome from a Soda check result object.

    Tries the ``outcome`` attribute first, then ``result``, then returns ``"unknown"``.
    """
    if hasattr(soda_check, "outcome"):
        return str(soda_check.outcome)
    if hasattr(soda_check, "result"):
        return str(soda_check.result)
    return "unknown"


def _get_check_name(soda_check: Any) -> str:
    """Extract a check name from a Soda check result object.

    Tries the ``name`` attribute first, then ``check_name``.
    """
    if hasattr(soda_check, "name") and soda_check.name is not None:
        return str(soda_check.name)
    return str(soda_check.check_name)


def _get_severity(soda_check: Any, default_severity: str = "warn") -> str:
    """Extract a severity from a Soda check result object.

    Returns ``soda_check.severity`` if present, otherwise ``default_severity``.
    """
    if hasattr(soda_check, "severity") and soda_check.severity is not None:
        return str(soda_check.severity)
    return default_severity


def _to_dagster_severity(severity: str) -> AssetCheckSeverity:
    """Convert a Soda severity string to a Dagster :py:class:`AssetCheckSeverity`.

    ``"error"`` or ``"fail"`` maps to ``ERROR``; ``"warn"``, ``"pass"``, or any other
    value maps to ``WARN``.
    """
    if severity in ("error", "fail"):
        return AssetCheckSeverity.ERROR
    return AssetCheckSeverity.WARN


def _filter_results_for_dataset(scan_results: Any, dataset: str) -> list[Any]:
    """Filter Soda scan results to only those matching ``dataset``.

    For each check result, checks the ``table`` attribute first, then ``table_name``.
    """
    matching: list[Any] = []
    for check_result in scan_results.checks:
        if hasattr(check_result, "table") and check_result.table is not None:
            table = check_result.table
        else:
            table = getattr(check_result, "table_name", None)
        if table == dataset:
            matching.append(check_result)
    return matching


